function spiralOrder(matrix) {
  const values = [];
  let top = 0;
  let bottom = matrix.length - 1;
  let left = 0;
  let right = matrix[0].length - 1;

  while (top <= bottom && left <= right) {
    for (let column = left; column <= right; column++) values.push(matrix[top][column]);
    top++;

    for (let row = top; row <= bottom; row++) values.push(matrix[row][right]);
    right--;

    if (top <= bottom) {
      for (let column = right; column >= left; column--) values.push(matrix[bottom][column]);
      bottom--;
    }

    if (left <= right) {
      for (let row = bottom; row >= top; row--) values.push(matrix[row][left]);
      left++;
    }
  }

  return values;
}

