function nextGreaterElements(values) {
  const result = Array(values.length).fill(-1);
  const stack = [];

  for (let index = 0; index < values.length; index++) {
    while (stack.length > 0 && values[index] > values[stack.at(-1)]) {
      result[stack.pop()] = values[index];
    }

    stack.push(index);
  }

  return result;
}

