function groupAnagrams(words) {
  const groups = new Map();

  for (const word of words) {
    const key = [...word].sort().join('');
    const group = groups.get(key) ?? [];
    group.push(word);
    groups.set(key, group);
  }

  return [...groups.values()];
}

